import { CalendarDate, type DateValue } from '@internationalized/date';

export function processDateRangeValue(value: { start?: string | null; end?: string | null }) {
  if (value.start && value.end) {
    const startDate = value.start.split('-').map(Number);
    const endDate = value.end.split('-').map(Number);
    const startDateValue: DateValue = new CalendarDate(startDate[0], startDate[1], startDate[2]);
    const endDateValue: DateValue = new CalendarDate(endDate[0], endDate[1], endDate[2]);
    const dateRange = {
      start: startDateValue,
      end: endDateValue,
    };
    return dateRange;
  }
  return undefined;
}
